INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Channel Link immer eine physische Verbindung?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch virtuell sein"}, {"text": "Ja", "correct": false, "because": "Logische Kanäle zählen auch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat ein Channel Link im Netzwerk?', 3, '[{"text": "Daten zwischen Punkten übertragen", "correct": true, "because": "Verbindet Kommunikationsendpunkte"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Ebene"}, {"text": "IP-Adressen zuweisen", "correct": false, "because": "Aufgabe von DHCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale definieren einen Channel Link?', 5, '[{"text": "Bandbreite", "correct": true, "because": "Bestimmt Durchsatz"}, {"text": "Latenz", "correct": true, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Protokollversion", "correct": false, "because": "Höhere Ebene"}, {"text": "Geräte-MAC", "correct": false, "because": "Nur für Adressierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Channel Link arbeitet auf Schicht 2. b) Er benötigt immer einen Switch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Switch nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse eines Channel Links?', 4, '[{"text": "Übertragungsrate", "correct": false, "because": "Entscheidend für Leistung"}, {"text": "Verbindungstyp", "correct": false, "because": "Definiert Kanal"}, {"text": "Softwareversion", "correct": true, "because": "Höhere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Channel Link auch drahtlos sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "WLAN ist ein Beispiel"}, {"text": "Nein", "correct": false, "because": "Nicht nur kabelgebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt ein Channel Link typischerweise?', 3, '[{"text": "Ethernet", "correct": true, "because": "Häufig auf Schicht 2"}, {"text": "TCP", "correct": false, "because": "Schicht 4"}, {"text": "HTTP", "correct": false, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Qualität eines Channel Links?', 5, '[{"text": "Signalstärke", "correct": true, "because": "Bei drahtlos entscheidend"}, {"text": "Interferenzen", "correct": true, "because": "Stören Übertragung"}, {"text": "CPU-Leistung", "correct": false, "because": "Endgeräte-spezifisch"}, {"text": "RAM-Größe", "correct": false, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Channel Link ist immer Punkt-zu-Punkt. b) Er unterstützt Multicast. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Kann auch Broadcast sein"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Channel Link?', 4, '[{"text": "Übertragungsmedium", "correct": false, "because": "Physisch oder virtuell nötig"}, {"text": "Endpunkte", "correct": false, "because": "Kommunikation erfordert sie"}, {"text": "Betriebssystem", "correct": true, "because": "Höhere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Channel Link nur für LAN gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WAN möglich"}, {"text": "Ja", "correct": false, "because": "Nicht beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einem Channel Link entscheidend?', 4, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Stabile Datenübertragung"}, {"text": "Kapazität", "correct": true, "because": "Bestimmt Durchsatz"}, {"text": "Verschlüsselung", "correct": false, "because": "Höhere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Channel Link immer verkabelt ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Drahtlos möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung eines Channel Links?', 3, '[{"text": "Stabile Verbindung", "correct": true, "because": "Grundlage für Kommunikation"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}, {"text": "Schnelle Installation", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Channel Link kann mehrere Geräte verbinden. b) Er arbeitet nur auf Schicht 1.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 2 häufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Channel Link?', 5, '[{"text": "Schnelle Datenübertragung", "correct": true, "because": "Optimiert Kommunikation"}, {"text": "Flexibilität", "correct": true, "because": "Physisch oder virtuell"}, {"text": "Automatische Updates", "correct": false, "because": "Software-spezifisch"}, {"text": "Datenkompression", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Channel Link unwichtig?', 3, '[{"text": "Übertragungsgeschwindigkeit", "correct": false, "because": "Kernmerkmal"}, {"text": "Verbindungszuverlässigkeit", "correct": false, "because": "Entscheidend"}, {"text": "Bildschirmgröße", "correct": true, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt ein Channel Link nur eine Richtung?', 3, '[{"text": "Nein", "correct": true, "because": "Bidirektional möglich"}, {"text": "Ja", "correct": false, "because": "Nicht eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Channel Link für VPNs genutzt wird?', 2, '[{"text": "Ja", "correct": true, "because": "Virtuelle Kanäle möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente ist für einen Channel Link essenziell?', 4, '[{"text": "Übertragungsmedium", "correct":-true, "because": "Physisch oder virtuell nötig"}, {"text": "Router", "correct": false, "because": "Nur bei Routing"}, {"text": "Firewall", "correct": false, "because": "Sicherheitsebene"}]');
